  .callout strong { color: var(--text); }
  .callout.warning {
    background: rgba(210,153,34,0.07);
    border-left-color: var(--accent3);
  }
  .callout.danger {
    background: rgba(248,81,73,0.07);
    border-left-color: var(--accent4);
  }

  /* ── Orbit definition table ── */
  .def-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 13px;
    margin-top: 16px;
  }
